1	package roombook
2	
3	import (
4		"errors"
5		"fmt"
6		"sort"
7		"time"
8	)
9	
10	var (
11		ErrConflict    = errors.New("room is already booked")
12		ErrMaintenance = errors.New("room is closed for maintenance")
13		ErrCleaning    = errors.New("room is being cleaned")
14		ErrBadInterval = errors.New("end must be after start")
15		ErrTooLong     = errors.New("bookings are limited to 4 hours")
16	)
17	
18	// Booking is one confirmed reservation. Its interval is half-open: a booking
19	// from 10:00 to 11:00 frees the room at 11:00.
20	type Booking struct {
21		ID    int
22		Room  string
23		Owner string
24		When  Interval
25	}
26	
27	// Calendar holds the bookings, maintenance windows and cleaning slots of all
28	// rooms.
29	type Calendar struct {
30		bookings    []Booking
31		maintenance map[string][]Interval
32		cleaning    map[string][]Interval
33		nextID      int
34	}
35	
36	func NewCalendar() *Calendar {
37		return &Calendar{maintenance: map[string][]Interval{}, cleaning: map[string][]Interval{}, nextID: 1}
38	}
39	
40	// Book reserves room for owner during when.
41	func (c *Calendar) Book(room, owner string, when Interval) (Booking, error) {
42		r, err := findRoom(room)
43		if err != nil {
44			return Booking{}, err
45		}
46		if !when.End.After(when.Start) {
47			return Booking{}, ErrBadInterval
48		}
49		if minutes(when) > 240 {
50			return Booking{}, ErrTooLong
51		}
52		if err := c.checkMaintenance(r.ID, when); err != nil {
53			return Booking{}, err
54		}
55		if err := c.checkCleaning(r.ID, when); err != nil {
56			return Booking{}, err
57		}
58		// Two bookings conflict when they overlap (see overlaps).
59		for _, b := range c.bookings {
60			if b.Room == r.ID && overlaps(b.When, when) {
61				return Booking{}, fmt.Errorf("%w: %s by %s", ErrConflict, formatSpan(b.When), b.Owner)
62			}
63		}
64		b := Booking{ID: c.nextID, Room: r.ID, Owner: owner, When: when}
65		c.nextID = c.nextID + 1
66		c.bookings = append(c.bookings, b)
67		return b, nil
68	}
69	
70	// Cancel removes a booking by id. It reports whether one was removed.
71	func (c *Calendar) Cancel(id int) bool {
72		for i := range c.bookings {
73			if c.bookings[i].ID == id {
74				c.bookings = append(c.bookings[:i], c.bookings[i+1:]...)
75				return true
76			}
77		}
78		return false
79	}
80	
81	// DaySchedule lists a room's bookings on the day of t, earliest first.
82	func (c *Calendar) DaySchedule(room string, t time.Time) []Booking {
83		out := []Booking{}
84		y, m, d := t.Date()
85		for _, b := range c.bookings {
86			by, bm, bd := b.When.Start.Date()
87			if b.Room == room && by == y && bm == m && bd == d {
88				out = append(out, b)
89			}
90		}
91		sort.Slice(out, func(i, j int) bool { return out[i].When.Start.Before(out[j].When.Start) })
92		return out
93	}
94	
95	func formatSpan(i Interval) string {
96		return i.Start.Format("15:04") + "-" + i.End.Format("15:04")
97	}
