3	import (
4		"errors"
5		"strings"
6	)
7	
8	// Room is a bookable meeting room.
9	type Room struct {
10		ID       string
11		Name     string
12		Capacity int
13		Floor    int
14	}
15	
16	var ErrUnknownRoom = errors.New("unknown room")
17	
18	var rooms = []Room{
19		{ID: "A1", Name: "Aurora", Capacity: 4, Floor: 1},
20		{ID: "A2", Name: "Borealis", Capacity: 8, Floor: 1},
21		{ID: "B1", Name: "Cumulus", Capacity: 12, Floor: 2},
22		{ID: "B2", Name: "Nimbus", Capacity: 20, Floor: 2},
23	}
24	
25	// findRoom looks a room up by id, ignoring case and surrounding spaces.
26	func findRoom(id string) (Room, error) {
27		id = strings.ToUpper(strings.TrimSpace(id))
28		var found Room
29		var ok bool = false
30		for i := 0; i < len(rooms); i++ {
31			if rooms[i].ID == id {
32				found = rooms[i]
33				ok = true
34			}
35		}
36		if ok == false {
37			return Room{}, ErrUnknownRoom
38		}
39		return found, nil
40	}
41	
42	// RoomsWithCapacity returns the rooms that seat at least n people.
43	func RoomsWithCapacity(n int) []Room {
44		out := []Room{}
45		for _, r := range rooms {
46			if r.Capacity >= n {
47				out = append(out, r)
48			}
49		}
50		return out
51	}
