7	)
8	
9	func at(h, m int) time.Time { return time.Date(2026, 3, 9, h, m, 0, 0, time.UTC) }
10	
11	func span(h1, m1, h2, m2 int) Interval { return Interval{Start: at(h1, m1), End: at(h2, m2)} }
12	
13	func TestBookAndConflict(t *testing.T) {
14		c := NewCalendar()
15		if _, err := c.Book("A1", "ana", span(9, 0, 10, 0)); err != nil {
16			t.Fatal(err)
17		}
18		if _, err := c.Book("a1 ", "ben", span(9, 30, 10, 30)); !errors.Is(err, ErrConflict) {
19			t.Fatalf("overlapping booking: got %v, want ErrConflict", err)
20		}
21		if _, err := c.Book("A2", "ben", span(9, 30, 10, 30)); err != nil {
22			t.Fatalf("other room: %v", err)
23		}
24	}
25	
26	func TestBackToBackBookings(t *testing.T) {
27		c := NewCalendar()
28		if _, err := c.Book("B1", "ana", span(10, 0, 11, 0)); err != nil {
29			t.Fatal(err)
30		}
31		if _, err := c.Book("B1", "ben", span(11, 0, 12, 0)); err != nil {
32			t.Fatalf("a meeting that starts when the previous one ends: got %v, want no error", err)
33		}
34	}
35	
36	func TestMaintenanceBlocks(t *testing.T) {
37		c := NewCalendar()
38		_ = c.CloseForMaintenance("B2", span(13, 0, 15, 0))
39		if _, err := c.Book("B2", "ana", span(14, 0, 14, 30)); !errors.Is(err, ErrMaintenance) {
40			t.Fatalf("got %v, want ErrMaintenance", err)
41		}
42		if _, err := c.Book("B2", "ana", span(15, 30, 16, 0)); err != nil {
43			t.Fatalf("after maintenance: %v", err)
44		}
45	}
46	
47	func TestUtilisation(t *testing.T) {
48		c := NewCalendar()
49		_, _ = c.Book("A1", "ana", span(9, 0, 10, 0))
50		_, _ = c.Book("A1", "ben", span(13, 0, 15, 0))
51		if got := c.Utilisation("A1", at(0, 0)); got != 30 {
52			t.Fatalf("utilisation = %d, want 30", got)
53		}
54	}
55	
56	func TestRejects(t *testing.T) {
57		c := NewCalendar()
58		if _, err := c.Book("Z9", "ana", span(9, 0, 10, 0)); !errors.Is(err, ErrUnknownRoom) {
59			t.Fatalf("got %v", err)
60		}
61		if _, err := c.Book("A1", "ana", span(10, 0, 9, 0)); !errors.Is(err, ErrBadInterval) {
62			t.Fatalf("got %v", err)
63		}
64		if _, err := c.Book("A1", "ana", span(8, 0, 12, 30)); !errors.Is(err, ErrTooLong) {
65			t.Fatalf("got %v", err)
66		}
67	}
