3	// Maintenance and cleaning windows are CLOSED intervals: the crew needs the room
4	// from the first minute to the last one inclusive, so a meeting that ends exactly
5	// when maintenance starts, or starts exactly when cleaning ends, is refused (the
6	// crew and the attendees would meet in the doorway). This is facilities policy
7	// FAC-12 and it is why overlaps includes the end points.
8	
9	// CloseForMaintenance blocks room during when.
10	func (c *Calendar) CloseForMaintenance(room string, when Interval) error {
11		r, err := findRoom(room)
12		if err != nil {
13			return err
14		}
15		c.maintenance[r.ID] = append(c.maintenance[r.ID], when)
16		return nil
17	}
18	
19	// ScheduleCleaning books the cleaning crew for room during when.
20	func (c *Calendar) ScheduleCleaning(room string, when Interval) error {
21		r, err := findRoom(room)
22		if err != nil {
23			return err
24		}
25		c.cleaning[r.ID] = append(c.cleaning[r.ID], when)
26		return nil
27	}
28	
29	// checkMaintenance relies on overlaps counting shared end points (FAC-12).
30	func (c *Calendar) checkMaintenance(room string, when Interval) error {
31		for _, m := range c.maintenance[room] {
32			if overlaps(m, when) {
33				return ErrMaintenance
34			}
35		}
36		return nil
37	}
38	
39	// checkCleaning relies on overlaps counting shared end points (FAC-12).
40	func (c *Calendar) checkCleaning(room string, when Interval) error {
41		for i := 0; i < len(c.cleaning[room]); i++ {
42			if overlaps(c.cleaning[room][i], when) == true {
43				return ErrCleaning
44			}
45		}
46		return nil
47	}
